/** Events */
export const events = {
	clusterStateChanged: makeEvent<ClusterStateChanged, ClusterStateChanged>("cluster-state-changed"),
	drainFinished: makeEvent<DrainFinished, DrainFinished>("drain-finished"),
	drainProgress: makeEvent<DrainProgress, DrainProgress>("drain-progress"),
	kubeconfigsChanged: makeEvent<KubeconfigsChanged, KubeconfigsChanged>("kubeconfigs-changed"),
	linkPending: makeEvent<LinkPending, LinkPending>("link-pending"),
	unsavedCloseRequested: makeEvent<UnsavedCloseRequested, UnsavedCloseRequested>("unsaved-close-requested"),
	updateProgress: makeEvent<UpdateProgress, UpdateProgress>("update-progress"),
};

/* Types */
/**  Result of an access check for one kind. */
export type AccessResult = {
	id: string,
	allowed: boolean,
};

/**
 *  Whether one action is allowed. `reason` is empty when it is, otherwise a
 *  sentence naming the first request RBAC refuses.
 */
export type ActionAccess = {
	id: string,
	allowed: boolean,
	reason: string,
};

/**  One action offered for a kind. */
export type ActionDef = {
	id: ActionId,
	label: string,
	/**
	 *  Needs a confirmation naming the object(s). (Scale asks again when the
	 *  target is 0, see [`scale_is_destructive`].)
	 */
	destructive: boolean,
	/**  The confirmation also makes the user type the object's name. */
	type_to_confirm: boolean,
	input: ActionInput,
};

export type ActionId = "delete" | "forceDelete" | "scale" | "restart" | "cordon" | "uncordon" | "drain" | "trigger" | "suspend" | "resume" | 
/**
 *  Start a port-forward. Long-running, so the UI and the CLI handle it
 *  themselves ([`crate::PortForward`]); [`run_action`] refuses it.
 */
"portForward" | 
/**
 *  Add an ephemeral debug container and attach to it. Interactive, so
 *  handled like [`ActionId::PortForward`] ([`crate::debug`]).
 */
"debug" | 
/**
 *  A root shell on a node through a privileged pod. Interactive
 *  ([`crate::node_shell`]).
 */
"nodeShell" | 
/**
 *  Attach to a container's main process (`kubectl attach -it`).
 *  Interactive ([`crate::attach`]).
 */
"attach" | 
/**
 *  Evict one pod through the Eviction API, so PodDisruptionBudgets
 *  are respected ([`evict_pod`]).
 */
"evict";

/**  An extra value the action needs before it can run. */
export type ActionInput = 
/**  Nothing more is needed. */
"none" | 
/**  A non-negative whole number of replicas. */
"replicas" | 
/**  A remote port (number or name) and an optional local port. */
"port" | 
/**  The container to debug and the debug image. */
"debug";

/**  The rolled-up status of an application. */
export type AppHealth = 
/**  A workload failed or has a failing replica. */
"Degraded" | 
/**  A workload is not fully ready yet. */
"Progressing" | 
/**  Every workload is fine. */
"Healthy" | 
/**  Every workload is suspended. */
"Suspended";

/**  Where an application's grouping comes from. */
export type AppSource = 
/**  A Helm release (its name is the release's). */
"Helm" | 
/**  The `app.kubernetes.io/instance` label. */
"Instance" | 
/**  The `app.kubernetes.io/name` label. */
"Name";

/**  A workload of an application. */
export type AppWorkload = {
	/**  API group and kind, to open its table. */
	group: string,
	kind: string,
	namespace: string,
	name: string,
	status: WorkloadStatus,
	/**  Why it is not fine ("0 of 2 ready"), or "". */
	problem: string,
};

/**  One application. */
export type Application = {
	/**  `namespace/name`, unique in a list. */
	key: string,
	namespace: string,
	name: string,
	source: AppSource,
	/**  The distinct `app.kubernetes.io/name` labels of its workloads, sorted. */
	components: string[],
	/**  The distinct `app.kubernetes.io/version` labels, sorted. */
	versions: string[],
	/**  The distinct `app.kubernetes.io/managed-by` labels, sorted. */
	managed_by: string[],
	health: AppHealth,
	/**  The first problem ("Deployment web: 0 of 2 ready"), or "". */
	reason: string,
	/**  Problem workloads first, then by kind and name. */
	workloads: AppWorkload[],
	/**  The oldest workload's creation (unix seconds). */
	created: number,
};

/**  The applications of the selected namespaces. */
export type ApplicationsList = {
	/**  Sorted by namespace and name. */
	applications: Application[],
	/**  What is missing or narrowed, and why (RBAC). */
	notes: string[],
};

/**  A message on an applications feed's channel. */
export type ApplicationsMessage = 
/**
 *  A new applications list (sent when it changed, at most about once a
 *  second).
 */
{ type: "update"; list: ApplicationsList } | 
/**  The feed's connection state changed. */
{
	type: "state",
} & WatchState;

/**  What an apply did. */
export type ApplyOutcome = 
/**
 *  Applied (or, for a dry run, would apply). `takeovers` are the fields
 *  it took (or would take) over from other field managers.
 */
{ outcome: "applied"; takeovers: FieldTakeover[] } | 
/**
 *  Someone else wrote to the object since it was loaded; nothing was
 *  applied. `resource_version` is the object's current one; `fields`
 *  the fields both the edit and the other writer changed (empty when
 *  that is not known); `reason` a sentence when the conflict is not
 *  about fields (the object was deleted and created again, or is being
 *  deleted), empty otherwise.
 */
{ outcome: "conflict"; resource_version: string; fields: string[]; reason: string } | 
/**
 *  The object changed on the server since it was loaded, in other
 *  fields than the edit; nothing was applied. `yaml` is the edit
 *  re-applied on the latest version (at `resource_version`), to review
 *  and save again; `changed` the fields the server changed.
 */
{ outcome: "rebased"; yaml: string; 
/**  The latest version as the editor loads it: the new base. */
latest: string; resource_version: string; changed: string[] };

/**  The result for one object of a manifest. */
export type ApplyResult = {
	/**  1-based position of its document in the file. */
	document: number,
	/**  1-based line its document starts on (for a YAML error: the error's line). */
	line: number,
	/**  Empty if the document could not be read. */
	api_version: string,
	kind: string,
	name: string,
	/**  Empty for cluster-scoped kinds. */
	namespace: string,
	status: ApplyStatus,
	/**  Why it failed, was skipped or is pending; empty otherwise. */
	message: string,
	/**  Fields the apply took (or would take) over from other field managers. */
	takeovers: FieldTakeover[],
};

/**  What happened to one object of a manifest. */
export type ApplyStatus = 
/**  It did not exist and was created (a dry run: would be). */
"created" | 
/**  It existed and changed. */
"configured" | 
/**  It existed and the apply changed nothing. */
"unchanged" | 
/**  The cluster rejected it, or the document could not be read. */
"failed" | 
/**  Not applied, because other documents failed validation. */
"skipped" | 
/**
 *  A dry run could not check it yet: it needs a CRD or a namespace that
 *  this same manifest creates.
 */
"pending";

/**  A CLI Ask AI can start. */
export type AskAiCli = {
	/**  `claude`, `codex`, `gemini` or `custom`. */
	id: string,
	label: string,
	/**  Where it was found (`""`: not found). */
	path: string,
	/**  How to install it (`""` for the custom command). */
	install: string,
	/**
	 *  The [`AskAiSkill::id`] of the skill it reads (`""`: none, the
	 *  guidance goes in its first prompt).
	 */
	skill: string,
};

/**  What Ask AI can start on this machine. */
export type AskAiSetup = {
	/**
	 *  The known CLIs found on `PATH`, then the custom command if it is set
	 *  and can run.
	 */
	found: AskAiCli[],
	/**  The known CLIs not on `PATH`, with how to install them. */
	missing: AskAiCli[],
	/**
	 *  The one Ask AI starts: the one set in Settings if it is found, else
	 *  the first found (`""`: none).
	 */
	chosen: string,
	/**  The `nauvi` CLI the skill runs (`""`: not on `PATH`). */
	nauvi: string,
	/**
	 *  Why the custom command set in Settings cannot run (`""`: it can, or
	 *  none is set).
	 */
	custom_error: string,
	/**  The skill in each place (`[]`: no home folder). */
	skills: AskAiSkill[],
};

/**  The nauvi skill in one place AI CLIs read skills from. */
export type AskAiSkill = {
	/**  `claude` or `agents`. */
	id: string,
	/**  The CLIs that read it. */
	label: string,
	/**  Its folder (`…/skills/nauvi`). */
	path: string,
	/**
	 *  `missing`, `current`, `outdated` (written by another version; Ask AI
	 *  updates it) or `foreign` (not nauvi's: left alone).
	 */
	state: string,
	/**  For `foreign`: why. */
	detail: string,
};

/**  A started Ask AI terminal. */
export type AskAiStarted = {
	session: string,
	context: string,
	namespace: string,
	/**  The CLI's name. */
	cli: string,
	/**
	 *  What the CLI got: `new` (the skill was installed now), `updated`,
	 *  `current`, or `prompt` (the guidance is in its first prompt).
	 */
	skill: string,
	/**  The skill's folder (`""` for `prompt`). */
	skill_path: string,
	/**  Why the skill could not be written (`""`: it was, or none is used). */
	skill_error: string,
	/**  The `nauvi` CLI is on `PATH`. */
	nauvi: boolean,
	/**  As in a local shell: the downloaded kubectl first on `PATH`. */
	kubectl: string,
	/**  The folder it runs in. */
	cwd: string,
	/**
	 *  `cwd` is the working directory set for the context (else it is Ask
	 *  AI's own folder).
	 */
	cwd_set: boolean,
};

/**  A saved forward that did not start automatically, and why. */
export type AutoStartError = {
	saved_id: string,
	error: string,
};

/**  Outcome of one object in a bulk delete. */
export type BulkItemResult = {
	/**  `namespace/name`, or `name` if cluster scoped. */
	key: string,
	/**  Plain-words reason; empty when the delete was accepted. */
	error: string,
};

/**
 *  Requests, limits and usage against what the nodes can allocate, like
 *  Lens. Limits sum the limits that are set: a container without one adds
 *  nothing, so they can be lower than the requests.
 */
export type Capacity = {
	cpu_requests_millicores: number,
	cpu_limits_millicores: number,
	/**
	 *  Running containers (app containers and native sidecars) without a
	 *  cpu limit: the limits above are no ceiling when this is not 0.
	 */
	cpu_unlimited_containers: number,
	cpu_allocatable_millicores: number,
	/**  0 unless `metrics`. */
	cpu_usage_millicores: number,
	memory_requests_bytes: number,
	memory_limits_bytes: number,
	/**  As `cpu_unlimited_containers`, for memory. */
	memory_unlimited_containers: number,
	memory_allocatable_bytes: number,
	/**  0 unless `metrics`. */
	memory_usage_bytes: number,
	/**  Whether usage came from the metrics API (metrics-server). */
	metrics: boolean,
	/**  Pods bound to a node that have not finished. */
	pods: number,
	pods_allocatable: number,
};

/**  Where a kind appears in the sidebar. */
export type Category = "workloads" | "network" | "config" | "storage" | "cluster" | 
/**  RBAC: ServiceAccounts, Roles, ClusterRoles and their bindings. */
"access" | 
/**  Dynamic Resource Allocation: DeviceClasses, ResourceClaims, ... */
"devices" | 
/**  CRDs, grouped by API group; the CRDs themselves are "Definitions". */
"custom" | 
/**  Anything else the server serves (apiservices, flowschemas, ...). */
"other";

/**  A running forward and the cluster it runs on (ADR 0007). */
export type ClusterForward = {
	/**  The cluster's id (its context id). */
	cluster: string,
	forward: ForwardInfo,
};

/**
 *  A cluster's proxy, for its settings page and diagnostics. No field
 *  holds a password.
 */
export type ClusterProxyInfo = {
	/**  The proxy set in the app, its user and password masked (`""`: none). */
	url: string,
	/**  Whether that URL has a user and password. */
	has_credentials: boolean,
	/**  Use the proxy for a cluster on this machine too. */
	local: boolean,
	/**
	 *  An https:// proxy's CA file, besides the system's trust store
	 *  (`""`: none).
	 */
	ca_file: string,
	/**  The kubeconfig's own proxy-url for the cluster, masked (`""`: none). */
	kubeconfig_proxy: string,
	/**  The API server is on this machine (localhost, 127.0.0.1, ::1). */
	server_local: boolean,
	/**  How the cluster's next connection goes, in a sentence. */
	route: string,
};

export type ClusterState = "connected" | 
/**  Disconnected because it was idle; the next command connects again. */
"idle" | 
/**  The window disconnected it (`cmd_cluster_disconnect`). */
"disconnected";

/**
 *  A cluster the window does not show changed state, or what keeps it
 *  connected changed. Sent to that window only.
 */
export type ClusterStateChanged = {
	cluster: string,
	state: ClusterState,
	/**
	 *  What keeps it connected (`[]` when nothing does, or it is not
	 *  connected).
	 */
	pinnedBy: Pin[],
};

/**  A table column as the UI sees it. */
export type ColumnDef = {
	key: string,
	label: string,
	kind: ColumnKind,
	/**
	 *  Off until the user turns it on in the column chooser (IP, QoS, ...);
	 *  the CLI's tables leave it out.
	 */
	default_hidden: boolean,
};

/**  How a column's cell is produced and rendered. */
export type ColumnKind = "text" | 
/**  Sorted numerically. */
"number" | 
/**  Derived from the creation time by the UI, so it stays fresh. */
"age" | 
/**  Coloured by value (Running, Pending, Failed, ...). */
"status" | 
/**  Live usage merged in by the UI from the metrics API. */
"podCpu" | "podMemory" | "nodeCpu" | "nodeMemory" | 
/**  A node's root filesystem, from Prometheus (node-exporter). */
"nodeDisk" | 
/**
 *  The controller of the object: `Kind/name`, or `Kind.group/name`
 *  outside the core, `apps` and `batch` groups. The UI links it to the
 *  owner's detail.
 */
"owner" | 
/**
 *  A pod's containers and their states (`init:setup=done app=ready`,
 *  see `pod_containers`), drawn by the UI as one square each.
 */
"containers" | 
/**
 *  What a Deployment, StatefulSet or DaemonSet controller is doing
 *  (`Running`, `Scaling`, `Updating`, `Failed`, ... see
 *  `workload_status`), drawn by the UI with a shape and a colour.
 */
"rollout" | 
/**
 *  The images of a pod or a workload's pod template (#547): the first
 *  line is what the cell shows (`mongo:7.0.1 +1`), each line after it a
 *  full reference, for the tooltip (see `image_column`).
 */
"image" | 
/**
 *  Image vulnerabilities (#535): filled by the UI from the image
 *  security listing it already holds, keyed by workload. Off by
 *  default, and not offered while image security is off.
 */
"vulns";

export type ConditionInfo = {
	type: string,
	status: string,
	reason: string,
	message: string,
	age: string,
};

export type Confirmed = {
	id: string,
	confirm: string,
};

export type ContainerDetail = {
	name: string,
	kind: ContainerKind,
	image: string,
	image_id: string,
	/**
	 *  The entrypoint override (`command`), empty for the image's own.
	 *  Values that look like secrets are replaced by `••••`.
	 */
	command: string[],
	/**  `args`, masked like `command`. */
	args: string[],
	/**  Whether anything in `command` or `args` was hidden. */
	secrets_hidden: boolean,
	state: StateInfo,
	last_state: StateInfo,
	ready: boolean,
	restarts: number,
	requests: { [key in string]: string },
	limits: { [key in string]: string },
	ports: PortInfo[],
	probes: ProbeInfo[],
	mounts: MountInfo[],
	env: EnvInfo[],
};

/**
 *  A container's environment: `envFrom` sources first, then `env`, the
 *  order the kubelet applies them in (later wins).
 */
export type ContainerEnv = {
	container: string,
	from: EnvFromGroup[],
	env: EnvValue[],
};

/**  One container of a pod template and its image. */
export type ContainerImage = {
	container: string,
	image: string,
	/**  `regular`, `init` or `ephemeral`, as in the pod panel. */
	kind: string,
};

export type ContainerKind = "init" | "regular" | "ephemeral";

/**  One container's samples (pods only). */
export type ContainerSeries = {
	name: string,
	samples: UsageSample[],
};

export type ContainerUsage = {
	name: string,
	cpu_millicores: number,
	memory_bytes: number,
};

/**  The result of checking one context. */
export type ContextCheck = {
	/**  The context id. */
	name: string,
	state: ContextState,
	/**  The error (`""` when connected). */
	message: string,
	/**  The API server's version (`""` unless connected). */
	version: string,
};

/**  A context in the catalog. */
export type ContextInfo = ContextInfo_Serialize | ContextInfo_Deserialize;

/**  A context in the catalog. */
export type ContextInfo_Deserialize = {
	/**
	 *  The context's id: its name, or `name (file)` when an earlier source
	 *  already has a context of that name. Commands take this id.
	 */
	name: string,
	/**  The context's name in its kubeconfig file. */
	context: string,
	current: boolean,
	/**  The context's default namespace (`contexts[].context.namespace`). */
	namespace?: string | null,
	/**  Its cluster's and user's names in the file, and the API server. */
	cluster: string,
	user: string,
	server: string,
	/**  The file that defines it. */
	file: string,
	/**
	 *  The added source it came from (a file, folder or pasted file);
	 *  `""` for the default kubeconfig.
	 */
	source: string,
	/**
	 *  The command logging in runs: the exec plugin's command and
	 *  arguments, or the gcp auth provider's `cmd-path` (`""`: none).
	 */
	login_command: string,
	/**
	 *  Logging in runs a plugin or an auth provider (`exec` or
	 *  `auth-provider`): the catalog checks it only when asked (#201).
	 */
	login_plugin: boolean,
	/**
	 *  Logging in runs a plugin that may ask the user ([`plugin_login`]):
	 *  the app never disconnects the cluster when it is idle (ADR 0007).
	 */
	plugin_login: boolean,
	/**
	 *  The `tokenFile`, `client-certificate` and `client-key` paths of an
	 *  added file's context outside that file's folder: logging in sends
	 *  them, so the catalog checks it only when asked (#244). `[]` for the
	 *  default kubeconfig.
	 */
	local_files: string[],
};

/**  A context in the catalog. */
export type ContextInfo_Serialize = {
	/**
	 *  The context's id: its name, or `name (file)` when an earlier source
	 *  already has a context of that name. Commands take this id.
	 */
	name: string,
	/**  The context's name in its kubeconfig file. */
	context: string,
	current: boolean,
	/**  The context's default namespace (`contexts[].context.namespace`). */
	namespace: string | null,
	/**  Its cluster's and user's names in the file, and the API server. */
	cluster: string,
	user: string,
	server: string,
	/**  The file that defines it. */
	file: string,
	/**
	 *  The added source it came from (a file, folder or pasted file);
	 *  `""` for the default kubeconfig.
	 */
	source: string,
	/**
	 *  The command logging in runs: the exec plugin's command and
	 *  arguments, or the gcp auth provider's `cmd-path` (`""`: none).
	 */
	login_command: string,
	/**
	 *  Logging in runs a plugin or an auth provider (`exec` or
	 *  `auth-provider`): the catalog checks it only when asked (#201).
	 */
	login_plugin: boolean,
	/**
	 *  Logging in runs a plugin that may ask the user ([`plugin_login`]):
	 *  the app never disconnects the cluster when it is idle (ADR 0007).
	 */
	plugin_login: boolean,
	/**
	 *  The `tokenFile`, `client-certificate` and `client-key` paths of an
	 *  added file's context outside that file's folder: logging in sends
	 *  them, so the catalog checks it only when asked (#244). `[]` for the
	 *  default kubeconfig.
	 */
	local_files: string[],
};

/**  How much a context lets the app change. */
export type ContextMode = "normal" | 
/**  Every change is refused. */
"readOnly" | 
/**  Every change needs the context's name typed as a confirmation. */
"protected";

/**
 *  What is remembered per kubeconfig context, by context id (#78), and set
 *  on its cluster settings page.
 */
export type ContextSettings = ContextSettings_Serialize | ContextSettings_Deserialize;

/**
 *  What is remembered per kubeconfig context, by context id (#78), and set
 *  on its cluster settings page.
 */
export type ContextSettings_Deserialize = {
	/**  The last view: `"overview"` or a kind id (`apps/v1/deployments`). */
	view?: string,
	/**  The selected namespaces (empty: all namespaces). */
	namespaces?: string[],
	/**  Namespaces typed in by a user who may not list them. */
	typed_namespaces?: string[],
	/**
	 *  The Prometheus Service for usage charts (#47): `""` detects one,
	 *  `"off"` turns it off, else `namespace/service:port`.
	 */
	prometheus?: string,
	/**  Shown instead of the context id (`""`: the id). */
	display_name?: string,
	/**  A CSS colour marking the cluster (`""`: none). */
	color?: string,
	/**
	 *  The namespace to start in when none is remembered (`""`: all
	 *  namespaces if allowed, else the context's own).
	 */
	default_namespace?: string,
	/**  Where local shells start (`""`: the home directory; `~` expands). */
	shell_cwd?: string,
	/**  When a window last connected to it, epoch milliseconds (0: never). */
	last_used?: number,
	/**
	 *  Hide CPU and memory usage for this cluster (#327): no metric
	 *  columns, usage charts or overview usage, and the metrics API is not
	 *  polled.
	 */
	hide_metrics?: boolean,
	/**
	 *  Read-only or protected (#338). Changed only through
	 *  `cmd_set_context_mode`: a settings patch keeps it, so a window with
	 *  an older copy of the settings cannot turn the protection off.
	 */
	mode?: ContextMode,
	/**
	 *  The kubeconfig file and context the mode was set for, which
	 *  `nauvi mcp` matches the mode by (#338). Kept with the mode.
	 */
	mode_source?: ModeSource_Deserialize,
	/**
	 *  Image security for this cluster (#534): as the app's setting, on
	 *  or off. Optional in TypeScript: the UI reads none as the default.
	 */
	image_security?: ImageSecurityMode,
};

/**
 *  What is remembered per kubeconfig context, by context id (#78), and set
 *  on its cluster settings page.
 */
export type ContextSettings_Serialize = {
	/**  The last view: `"overview"` or a kind id (`apps/v1/deployments`). */
	view: string,
	/**  The selected namespaces (empty: all namespaces). */
	namespaces: string[],
	/**  Namespaces typed in by a user who may not list them. */
	typed_namespaces: string[],
	/**
	 *  The Prometheus Service for usage charts (#47): `""` detects one,
	 *  `"off"` turns it off, else `namespace/service:port`.
	 */
	prometheus: string,
	/**  Shown instead of the context id (`""`: the id). */
	display_name: string,
	/**  A CSS colour marking the cluster (`""`: none). */
	color: string,
	/**
	 *  The namespace to start in when none is remembered (`""`: all
	 *  namespaces if allowed, else the context's own).
	 */
	default_namespace: string,
	/**  Where local shells start (`""`: the home directory; `~` expands). */
	shell_cwd: string,
	/**  When a window last connected to it, epoch milliseconds (0: never). */
	last_used: number,
	/**
	 *  Hide CPU and memory usage for this cluster (#327): no metric
	 *  columns, usage charts or overview usage, and the metrics API is not
	 *  polled.
	 */
	hide_metrics: boolean,
	/**
	 *  Read-only or protected (#338). Changed only through
	 *  `cmd_set_context_mode`: a settings patch keeps it, so a window with
	 *  an older copy of the settings cannot turn the protection off.
	 */
	mode: ContextMode,
	/**
	 *  The kubeconfig file and context the mode was set for, which
	 *  `nauvi mcp` matches the mode by (#338). Kept with the mode.
	 */
	mode_source: ModeSource_Serialize,
	/**
	 *  Image security for this cluster (#534): as the app's setting, on
	 *  or off. Optional in TypeScript: the UI reads none as the default.
	 */
	image_security?: ImageSecurityMode,
};

export type ContextState = "connected" | 
/**  The credentials or the exec plugin failed. */
"auth_error" | "certificate_error" | "unreachable" | 
/**  The kubeconfig entry itself is broken (no cluster, unreadable file). */
"invalid" | 
/**
 *  Logging in runs a command of an added kubeconfig that the user has
 *  not allowed (set by the desktop app, #201).
 */
"not_allowed" | 
/**
 *  Logging in sends local files from outside an added kubeconfig's
 *  folder (a token file, a client certificate): checked only when the
 *  user asks (set by the desktop app, #244).
 */
"local_files";

/**  A column the user added to a kind's table. */
export type CustomColumn = {
	/**  Unique within the kind; the column's key is [`custom_key`] of it. */
	id: string,
	/**  The header. */
	label: string,
	source: CustomSource,
	/**  The label key, annotation key or field path. */
	value: string,
	/**
	 *  The context it was added in, for a kind defined by a CRD (`""`:
	 *  every context). The backend does not look at it.
	 */
	context: string,
};

/**  Where a custom column's value comes from. */
export type CustomSource = 
/**  `metadata.labels[value]`. */
"label" | 
/**  `metadata.annotations[value]`. */
"annotation" | 
/**  A field path (`.status.podIP`). */
"field";

/**  One change of a data save. */
export type DataChange = {
	key: string,
	field: DataField,
	/**  Removes the key; `value` is ignored. */
	delete: boolean,
	value: string,
	encoding: DataEncoding,
};

/**  How a value is written. */
export type DataEncoding = 
/**  The value as text (UTF-8). */
"text" | 
/**  The bytes, base64-encoded. */
"base64";

/**  The data of a Secret or ConfigMap, and the version it was read at. */
export type DataEntries = {
	resource_version: string,
	/**  `immutable: true`: the API server refuses any change of the data. */
	immutable: boolean,
	entries: DataEntry[],
};

/**  One key of a Secret or ConfigMap. */
export type DataEntry = {
	key: string,
	field: DataField,
	/**  Size of the (decoded) value. */
	bytes: number,
	/**  Not valid UTF-8: shown (and edited) as base64. */
	binary: boolean,
	/**
	 *  A Secret's values are never listed: empty and `hidden` until
	 *  [`reveal_data_value`]. A ConfigMap's value is here, as text, or as
	 *  base64 if `binary`.
	 */
	value: string,
	hidden: boolean,
};

/**  Which map of the object an entry is in. */
export type DataField = 
/**  `data`: base64 in a Secret, text in a ConfigMap. */
"data" | 
/**  A ConfigMap's `binaryData` (base64). */
"binaryData";

/**  What a detail watch reports. */
export type DetailState = 
/**  The object as it is now. */
{ state: "detail"; detail: ResourceDetail } | 
/**  The object no longer exists (it may come back with the same name). */
{ state: "deleted" } | 
/**  The watch failed and is retrying; the last detail is still shown. */
{ state: "error"; error: string };

/**  The facts in About and in the copied diagnostics. */
export type Diagnostics = {
	version: string,
	commit: string,
	/**  The OS and its version, e.g. "Ubuntu 24.04.1 LTS, Linux 6.8.0". */
	os: string,
	arch: string,
	/**  The webview engine and its version. */
	webview: string,
	/**  Whether this is a debug build (`cargo tauri dev`). */
	debug_build: boolean,
	/**  All of the above as text, for the clipboard and a bug report. */
	text: string,
};

/**  Progress of a drain. */
export type DrainEvent = { type: "cordoned"; node: string } | 
/**  What the drain is going to do. */
{ type: "planned"; to_evict: number; 
/**  DaemonSet, mirror and already terminating pods left alone. */
skipped: number; 
/**  Of those to evict, pods without a controller: nothing recreates them. */
unmanaged: number } | { type: "evicted"; namespace: string; name: string } | 
/**  A PodDisruptionBudget refused the eviction; retrying. */
{ type: "waitingOnPdb"; namespace: string; name: string; message: string } | { type: "failed"; namespace: string; name: string; error: string };

/**
 *  A node drain ended. `error` is empty when it ran to the end (see
 *  `summary`) and says why not otherwise (for instance 403 on cordon).
 */
export type DrainFinished = {
	drainId: string,
	summary: DrainSummary,
	error: string,
};

/**  Progress of a node drain started by `cmd_drain_node`. */
export type DrainProgress = {
	drainId: string,
	event: DrainEvent,
};

export type DrainSummary = {
	evicted: number,
	failed: number,
	skipped: number,
	/**  Evicted pods that had not finished terminating when the timeout hit. */
	still_terminating: number,
};

/**  One `envFrom` source and the variables it provides. */
export type EnvFromGroup = {
	/**  `configmap` or `secret` (`unknown` for neither). */
	kind: EnvSourceKind,
	object: string,
	prefix: string,
	optional: boolean,
	/**  Why the source's keys are unknown; `rows` is then empty. */
	error: string,
	rows: EnvValue[],
};

/**  An env variable. Literal values are never included. */
export type EnvInfo = {
	/**  The variable, or `<prefix>*` for a whole `envFrom` source. */
	name: string,
	/**
	 *  Empty for a literal value, else `secret:name/key`, `configmap:name/key`,
	 *  `field:metadata.name`, `resource:limits.cpu`, or for `envFrom`
	 *  `secret:name` / `configmap:name`.
	 */
	source: string,
};

/**  Where a variable's value comes from. */
export type EnvSourceKind = "literal" | "configmap" | "secret" | "field" | "resource" | "unknown";

/**  One variable of a container, as the container sees it. */
export type EnvValue = {
	/**  The variable (with the `envFrom` prefix). */
	name: string,
	kind: EnvSourceKind,
	/**  The ConfigMap or Secret (empty for other kinds). */
	object: string,
	/**  Its key; the field path of a `field`, the resource of a `resource`. */
	key: string,
	/**
	 *  The value: a literal, a ConfigMap value or a resolved field. Empty
	 *  when `hidden`, on an `error`, or for a `resource`.
	 */
	value: string,
	/**
	 *  The value is withheld: always for a Secret, and for a literal that
	 *  looks like a secret. Revealed one at a time on request.
	 */
	hidden: boolean,
	/**  Why there is no value ("ConfigMap app-cfg not found", ...). */
	error: string,
	/**
	 *  A later variable of the same name wins: this one is not what the
	 *  container sees.
	 */
	overridden: boolean,
};

/**  A warning event, linked to the object it is about. */
export type EventInfo = {
	/**  `namespace/name` of the event. */
	key: string,
	/**  The event type: `Warning` or `Normal`. */
	kind: string,
	reason: string,
	message: string,
	/**  `Kind/name` of the involved object, for display. */
	object: string,
	object_api_version: string,
	object_kind: string,
	/**  Empty for cluster-scoped objects. */
	object_namespace: string,
	object_name: string,
	/**  When it last happened (unix seconds), so a UI can show its age. */
	time: number,
	count: number,
};

/**  The user's answer for one command of one source. */
export type ExecAnswer = 
/**  Not asked yet (or the source was added again). */
"unanswered" | "allowed" | "denied";

/**  A login command of an added source, and the contexts that run it. */
export type ExecCommand = {
	/**  The command line, as it runs. */
	command: string,
	/**  The ids of the contexts that log in with it. */
	contexts: string[],
	answer: ExecAnswer,
};

/**  What is known about a vulnerability being exploited (#537). */
export type Exploit = {
	/**
	 *  Known to be exploited in the wild: in CISA's KEV catalogue, as the
	 *  scanner (Grype) says or as the catalogue nauvi downloaded (opt-in).
	 */
	kev: boolean,
	/**
	 *  EPSS: the probability of exploitation in the next 30 days (0 to 1),
	 *  only where the scanner gives it (Grype); 0 when it gives none.
	 */
	epss: number | null,
	/**
	 *  Its percentile among all scored vulnerabilities (0 to 1), 0 when
	 *  not given.
	 */
	epss_percentile: number | null,
	/**  Grype's risk score, 0 when it gives none. */
	risk: number | null,
};

export type Fact = {
	label: string,
	value: string,
};

/**  Fields an apply took over from another field manager. */
export type FieldTakeover = {
	/**  The manager that owned the fields (e.g. "kubectl-create", "helm"). */
	manager: string,
	/**  Field paths, as the API server reports them (e.g. ".spec.replicas"). */
	fields: string[],
};

/**
 *  The vulnerabilities one package upgrade would fix (or that have no fix
 *  yet): one package at one installed version.
 */
export type FixGroup = {
	package: string,
	installed_version: string,
	/**
	 *  The distinct fixed versions of its vulnerabilities, sorted; empty
	 *  when none has a fix.
	 */
	fixed_in: string[],
	counts: SeverityCounts,
	/**  How many of `counts` have a fixed version. */
	fixable: number,
	/**  The vulnerability ids, worst first. */
	ids: string[],
};

/**  One running forward, with its live status. */
export type ForwardInfo = {
	id: string,
	/**  The saved forward it runs (see `cmd_portforward_saved`). */
	saved_id: string,
	target: ForwardTarget,
	/**  The remote port as asked for: a number or a port name. */
	remote: string,
	/**  Its number on the target (the Service port or the pod port). */
	remote_port: number,
	local_port: number,
	/**  `http://127.0.0.1:<local_port>`, or `https://` for a TLS target. */
	url: string,
	/**  Epoch milliseconds. */
	started_at: number,
	status: ForwardStatus,
};

/**  The kind of object a forward points at. */
export type ForwardKind = "pod" | "service" | "deployment" | "statefulSet" | "replicaSet" | "daemonSet";

/**  Live state of a forward. */
export type ForwardStatus = {
	/**  The pod the last connection went to (empty before the first one). */
	pod: string,
	/**  Connections open right now. */
	connections: number,
	/**  Connections served since the start. */
	total_connections: number,
	/**
	 *  What went wrong last, in plain words; empty once a later connection
	 *  got an answer.
	 */
	last_error: string,
};

/**  The object a forward points at. */
export type ForwardTarget = {
	kind: ForwardKind,
	namespace: string,
	name: string,
};

/**  What `helm show` tells about one chart version. */
export type HelmChartDetails = {
	/**  `repo/chart`, as asked. */
	chart: string,
	version: string,
	app_version: string,
	description: string,
	/**  The chart's home page; empty if it names none. */
	home: string,
	/**  `README.md`; empty if the chart has none. */
	readme: string,
	/**  The chart's default `values.yaml`. */
	values: string,
};

/**  The chart of one revision, for the list's chart columns. */
export type HelmChartInfo = {
	namespace: string,
	name: string,
	revision: number,
	chart: string,
	chart_version: string,
	app_version: string,
	/**  Why the payload could not be read; empty on success. */
	error: string,
};

/**  One version of a chart in a repository, as `helm search repo` lists it. */
export type HelmChartVersion = {
	/**  `repo/chart`. */
	name: string,
	version: string,
	app_version: string,
	description: string,
};

/**  What to install or upgrade, and how. */
export type HelmDeployRequest = {
	/**  The release name. */
	name: string,
	namespace: string,
	/**  `repo/chart` (or a chart directory or archive, from the CLI). */
	chart: string,
	/**  The chart version; empty for the newest. */
	version: string,
	/**
	 *  The user values as YAML: on an upgrade they replace the release's
	 *  values (`--reset-values`). Empty: the chart defaults.
	 */
	values: string,
	/**  Install only: create the namespace if it does not exist. */
	create_namespace: boolean,
	/**
	 *  Render and validate against the cluster (`--dry-run=server`) without
	 *  changing anything.
	 */
	dry_run: boolean,
	/**  Show Secret values in the returned manifest. */
	reveal: boolean,
	/**
	 *  Where helm keeps the release (`HELM_DRIVER`): on an upgrade, where
	 *  it is stored now; on an install, Secrets (helm's default) or ConfigMaps.
	 */
	storage: HelmStorage,
};

/**  The release helm installed, upgraded or (dry run) would have. */
export type HelmDeployResult = {
	name: string,
	namespace: string,
	revision: number,
	/**  `deployed`, or `pending-install` / `pending-upgrade` for a dry run. */
	status: string,
	chart: string,
	chart_version: string,
	app_version: string,
	notes: string,
	/**
	 *  The rendered manifest (without hooks, like a stored release's);
	 *  Secret values hidden unless revealed.
	 */
	manifest: string,
	/**
	 *  An upgrade's dry run: the release's current manifest, hidden like
	 *  `manifest`, which `summary` compares it with. Empty otherwise.
	 */
	previous_manifest: string,
	secrets_hidden: boolean,
	resources: HelmResource[],
	dry_run: boolean,
	/**  One line for a notice. */
	summary: string,
};

/**  One revision of a release, decoded. */
export type HelmRelease = {
	name: string,
	namespace: string,
	revision: number,
	status: string,
	storage: HelmStorage,
	chart: string,
	chart_version: string,
	app_version: string,
	description: string,
	notes: string,
	/**  As Helm stores them (RFC 3339); empty if unknown. */
	first_deployed: string,
	last_deployed: string,
	/**  The user-supplied values as YAML; empty if there are none. */
	values: string,
	/**  The chart defaults with the user values on top, as YAML. */
	computed_values: string,
	/**  The rendered manifest; Secret values hidden unless revealed. */
	manifest: string,
	/**  Whether `manifest` has hidden Secret values. */
	secrets_hidden: boolean,
	resources: HelmResource[],
	/**  Every stored revision, newest first. */
	history: HelmRevision[],
};

/**
 *  The releases in the asked namespaces, and the namespaces that could not
 *  be read, in plain words.
 */
export type HelmReleaseList = {
	/**  Sorted by namespace, then name. */
	releases: HelmReleaseRow[],
	warnings: string[],
};

/**  A release in a list: its newest revision and all revisions' labels. */
export type HelmReleaseRow = {
	name: string,
	namespace: string,
	revision: number,
	status: string,
	updated: number,
	storage: HelmStorage,
	/**  Every stored revision, newest first. */
	history: HelmRevision[],
};

/**  One configured chart repository. */
export type HelmRepo = {
	name: string,
	url: string,
};

/**
 *  The outcome of `helm repo update`: helm reports an unreachable
 *  repository but carries on with the others.
 */
export type HelmRepoUpdate = {
	/**  The repositories whose index was downloaded. */
	updated: string[],
	/**  One plain sentence per repository that could not be updated. */
	failed: string[],
};

/**  One object of a release's manifest. */
export type HelmResource = {
	api_version: string,
	kind: string,
	/**
	 *  As in the manifest, else the release's namespace (also for
	 *  cluster-scoped kinds: callers that know the kind ignore it).
	 */
	namespace: string,
	name: string,
};

/**  One revision, from its labels. */
export type HelmRevision = {
	revision: number,
	/**  `deployed`, `superseded`, `failed`, `pending-upgrade`, ... */
	status: string,
	/**
	 *  Unix seconds of the last change (the `modifiedAt` label, else the
	 *  object's creation); 0 if unknown.
	 */
	updated: number,
};

/**  Which revision to fetch for [`release_charts`]. */
export type HelmRevisionKey = {
	namespace: string,
	name: string,
	revision: number,
	storage: HelmStorage,
};

/**
 *  Where a release is stored: Helm's default Secret driver or the
 *  ConfigMap one. (Helm's `sql` driver keeps releases outside the cluster,
 *  where nauvi does not look.)
 */
export type HelmStorage = "secret" | "configmap";

/**  An item of the Help menu. */
export type HelpItem = 
/**  The docs of this version, in the browser. */
"documentation" | 
/**  A new GitHub issue with the diagnostics filled in. */
"report_bug" | 
/**  The folder with the app log, in the file manager. */
"log_folder" | 
/**  The docs' page on Ask AI and AI assistants (#376, #466). */
"ai_assistants" | 
/**  The docs' steps for opening a cluster, from the welcome screen (#485). */
"get_started";

/**  One ignore. */
export type IgnoreRule = IgnoreRule_Serialize | IgnoreRule_Deserialize;

/**  One ignore. */
export type IgnoreRule_Deserialize = {
	/**  `CVE-2024-1234`, `GHSA-xxxx-xxxx-xxxx`. */
	id?: string,
	scope?: IgnoreScope,
	/**  The cluster (its context id) of a workload or namespace ignore. */
	context?: string,
	/**
	 *  The image of an image ignore, as listed (`nginx:1.27`): every tag
	 *  of its repository is covered.
	 */
	image?: string,
	/**  The namespace of a workload or namespace ignore. */
	namespace?: string,
	/**  The workload of a workload ignore: `Deployment`, `web`. */
	kind?: string,
	name?: string,
	/**  Why it is ignored. Required. */
	reason?: string,
	/**  When it stops applying (unix seconds), 0 for never. */
	expires?: number,
	/**  When it was added (unix seconds), 0 when not known. */
	added?: number,
	/**  Read from the ignore file (not one of nauvi's own). */
	from_file?: boolean,
};

/**  One ignore. */
export type IgnoreRule_Serialize = {
	/**  `CVE-2024-1234`, `GHSA-xxxx-xxxx-xxxx`. */
	id: string,
	scope: IgnoreScope,
	/**  The cluster (its context id) of a workload or namespace ignore. */
	context: string,
	/**
	 *  The image of an image ignore, as listed (`nginx:1.27`): every tag
	 *  of its repository is covered.
	 */
	image: string,
	/**  The namespace of a workload or namespace ignore. */
	namespace: string,
	/**  The workload of a workload ignore: `Deployment`, `web`. */
	kind: string,
	name: string,
	/**  Why it is ignored. Required. */
	reason: string,
	/**  When it stops applying (unix seconds), 0 for never. */
	expires: number,
	/**  When it was added (unix seconds), 0 when not known. */
	added: number,
	/**  Read from the ignore file (not one of nauvi's own). */
	from_file: boolean,
};

/**  What an ignore covers. */
export type IgnoreScope = 
/**  Every image of one repository (`nginx`, any tag or digest). */
"image" | 
/**  One workload (its kind, namespace and name) of one cluster. */
"workload" | 
/**  Every image in one namespace of one cluster. */
"namespace" | 
/**  Everywhere: the lines of a `.trivyignore`. */
"everywhere";

/**  A finding an ignore covers (#537): shown apart, with its reason. */
export type IgnoredVuln = {
	vulnerability: Vulnerability,
	reason: string,
	/**  From the ignore file, not one of nauvi's own ignores. */
	from_file: boolean,
	/**  When the ignore ends (unix seconds), 0 for never. */
	expires: number,
};

/**  One image with its full (newest) report. */
export type ImageDetail = {
	image: ImageVulns,
	/**  Worst first, after the filters. */
	vulnerabilities: Vulnerability[],
	/**  Worst first, after the filters. */
	fix_groups: FixGroup[],
	/**  What an ignore covers (#537), not in `vulnerabilities`. */
	ignored: IgnoredVuln[],
};

/**  What the view shows: the listing and when its reports were read. */
export type ImageSecurityList = {
	summary: VulnsSummary,
	/**
	 *  When nauvi read the reports (unix seconds): the listing may come
	 *  from the cache.
	 */
	read_at: number,
};

/**  A cluster's own choice (its cluster settings), over the app's. */
export type ImageSecurityMode = 
/**  As Settings → Image security says. */
"default" | "on" | "off";

