/**  Settings → Image security. */
export type ImageSecuritySettings_Deserialize = {
	/**
	 *  Read the Trivy Operator's reports for clusters left on "default".
	 *  Off: nothing is read anywhere unless a cluster turns it on.
	 */
	enabled?: boolean,
	/**  Count (and show) only vulnerabilities this bad or worse. */
	min_severity?: Severity,
	/**  Count only what has a fixed version. */
	only_fixable?: boolean,
	/**  Namespaces whose images are never shown (`kube-system`...). */
	excluded_namespaces?: string[],
	/**
	 *  How long a listing is reused before the reports are read again
	 *  (Refresh always reads them), within `CACHE_TTL_RANGE`.
	 */
	cache_ttl_hours?: number,
	/**
	 *  Where vulnerabilities come from (#536): the cluster's reports, a
	 *  scanner on this computer, or both.
	 */
	source?: VulnSource,
	/**  The local scanner. */
	scanner?: ScannerKind,
	/**  Trivy's `--db-repository`, empty for its default. */
	db_repository?: string,
	/**  Do not let the scanner update its database. */
	skip_db_update?: boolean,
	/**  A Trivy server (`--server`), empty to scan on this computer. */
	server_url?: string,
	/**
	 *  A `.trivyignore` whose ids are ignored everywhere (#537), empty for
	 *  none.
	 */
	ignore_file?: string,
	/**  nauvi's own ignores (#537): each with a scope and a reason. */
	ignores?: IgnoreRule_Deserialize[],
	/**
	 *  Download CISA's catalogue of known exploited vulnerabilities
	 *  (#537). Off: nothing is downloaded.
	 */
	kev_download?: boolean,
};

