/**
 *  How bad a vulnerability is, as the scanner rates it. Ordered from
 *  `Unknown` (lowest) to `Critical`.
 */
export type Severity = "unknown" | "low" | "medium" | "high" | "critical";

/**  Vulnerabilities by severity. */
export type SeverityCounts = {
	critical: number,
	high: number,
	medium: number,
	low: number,
	unknown: number,
};

/**  One source of contexts, for the catalog's list of sources. */
export type SourceInfo = {
	path: string,
	kind: SourceKind,
	/**  Contexts it brought in (duplicates of earlier sources included). */
	contexts: number,
	/**  Kubeconfig files read (a folder may hold several). */
	files: number,
	/**  Why it could not be read (`""`: it was read). */
	error: string,
};

/**  Where a source of contexts comes from. */
export type SourceKind = 
/**  A file of the default kubeconfig (`KUBECONFIG` or `~/.kube/config`). */
"kubeconfig" | 
/**  A kubeconfig file the user added. */
"file" | 
/**  A folder the user added: every kubeconfig file in it. */
"folder" | 
/**  A kubeconfig pasted into the app, saved in its config directory. */
"pasted";

/**  A downsampled series for a table cell's sparkline. */
export type Spark = {
	cpu: number[],
	memory: number[],
};

/**  A container state (current or last). `state` is empty when there is none. */
export type StateInfo = {
	/**  `running`, `waiting`, `terminated`, or empty. */
	state: string,
	reason: string,
	message: string,
	/**  Only meaningful when terminated. */
	exit_code: number,
	/**  Age of the start (running) or the finish (terminated). */
	since: string,
};

/**  How many objects of one status. */
export type StatusCount = {
	status: WorkloadStatus,
	count: number,
};

/**  Tags of one group, newest first, at most [`GROUP_MAX`]. */
export type TagGroup = {
	tags: TagInfo[],
	/**  How many more there are. */
	more: number,
};

/**  One tag in a group. */
export type TagInfo = {
	tag: string,
	/**
	 *  When it was pushed (RFC 3339), from Docker Hub; `""` elsewhere or
	 *  unknown.
	 */
	updated: string,
};

/**  What the registry has for an image. */
export type TagReport = {
	/**  The image as the pod names it. */
	image: string,
	/**  `docker.io`, `ghcr.io`, `registry.example.com:5000`. */
	registry: string,
	/**  `library/mongo`. */
	repository: string,
	/**  The running tag (`""` for an image pinned by digest only). */
	tag: string,
	/**  The tag's numbers (`7.0.1`), `""` when it is not a version. */
	version: string,
	/**  What follows them (`-jammy`), kept in every suggestion. */
	variant: string,
	patch: TagGroup,
	minor: TagGroup,
	major: TagGroup,
	/**  Tags that are not versions (`latest`, `stable`). */
	other: TagGroup,
	/**  Tags read from the registry. */
	tag_count: number,
	/**  The list was longer than nauvi reads ([`MAX_TAGS`] or [`MAX_PAGES`]). */
	truncated: boolean,
	state: TagState,
	/**  The tag's digest in the registry (`""`: unknown). */
	registry_digest: string,
	/**  What the pod runs, from its `imageID` (`""`: unknown). */
	running_digest: string,
	/**  When the report was read from the registry (epoch seconds). */
	fetched_at: number,
};

/**  The running tag compared with the registry. */
export type TagState = 
/**  The tag still points at what the pod runs. */
"unchanged" | 
/**  The tag was pushed again: it points at another digest now. */
"updated" | 
/**  The registry no longer has the tag. */
"gone" | 
/**
 *  Not known: no digest from the registry, or the pod's `imageID` says
 *  none (not pulled yet, loaded by hand).
 */
"unknown";

/**  A log line and where it came from. */
export type TaggedLine = {
	pod: string,
	container: string,
	line: string,
};

/**  A message about a terminal session, other than its output. */
export type TermEvent = 
/**  The shell exited, or the session was closed or detached. */
{ type: "closed" } | 
/**
 *  After Ctrl-C: the output still waiting was dropped; output sent
 *  before this message is stale and the tab drops it too.
 */
{ type: "cleared" };

/**
 *  A message on a terminal channel as the UI sees it: output
 *  (`ArrayBuffer`) or a `TermEvent`. Only for `bindings.ts`; the backend
 *  sends a `TermFrame`.
 */
export type TermMessage = ArrayBuffer | TermEvent;

export type Theme = 
/**  Follow the system's light or dark preference. */
"system" | "dark" | "light";

/**
 *  The zone times are shown in (#330): clocks in charts, notifications and
 *  the footer, and "Jump to time" in the log viewer.
 */
export type TimeZone = "local" | "utc";

/**
 *  What Settings → Image security shows about the ignores and the
 *  catalogue.
 */
export type TriageStatus = {
	/**  The ignore file's ignores (0 without a file). */
	file_rules: number,
	/**
	 *  Why the ignore file cannot be read, empty when it can (or none is
	 *  set).
	 */
	file_error: string,
	/**  Its lines that were not understood (at most 20). */
	file_skipped: string[],
	/**  A catalogue is kept (and used while the setting is on). */
	kev_kept: boolean,
	/**  `2026.11.25`. */
	kev_version: string,
	/**  How many vulnerabilities it lists. */
	kev_count: number,
	/**  When it was downloaded (unix seconds), 0 when none is kept. */
	kev_fetched_at: number,
	/**  The address it comes from. */
	kev_url: string,
};

/**
 *  Closing this window (`quit`: quitting the app) was stopped because it has
 *  unsaved edits: ask the user, and call `cmd_discard_and_close` if they
 *  discard them.
 */
export type UnsavedCloseRequested = {
	quit: boolean,
};

/**  What a check found. Fields that do not apply are empty. */
export type UpdateCheck = {
	status: UpdateStatus,
	/**  The version running now. */
	current_version: string,
	/**  The version offered (when `available`). */
	version: string,
	/**  The release notes from `latest.json`. */
	notes: string,
	/**  The release page, for the notes and for installing by hand. */
	release_url: string,
	/**  Whether Install works here (see `updater::install_support`). */
	can_install: boolean,
	/**  Why the check was skipped, or why Install is not offered. */
	note: string,
	/**
	 *  The command that updates this copy instead of Install, for a .deb
	 *  from the apt repository (empty: none).
	 */
	update_command: string,
};

export type UpdatePhase = "downloading" | 
/**  Downloaded and verified; installing, then restarting. */
"installing";

/**  Progress of `cmd_update_install`, sent to the window that started it. */
export type UpdateProgress = {
	phase: UpdatePhase,
	/**  Bytes downloaded so far. */
	downloaded: number,
	/**  The download's size in bytes (`0`: not known). */
	total: number,
};

export type UpdateStatus = 
/**  No check ran: see `note`. */
"skipped" | "up_to_date" | "available";

export type UsageHistoryView = {
	history: SeriesView,
	reference: UsageReference,
	source: UsageSource,
	/**  The range shown: the one asked for, or `live` after a fallback. */
	range: UsageRange,
	/**  The Prometheus of this context (`namespace/service:port`), or "". */
	prometheus: string,
	/**
	 *  Why Prometheus was not used for a range that asked for it ("" when it
	 *  was, or for `live`).
	 */
	note: string,
};

/**  How far back a chart goes. */
export type UsageRange = 
/**  The metrics-server history the app collects (30 minutes). */
"live" | "1h" | "6h" | "24h";

/**
 *  What usage is compared against. 0 = not set (no request, no limit, or
 *  not a pod / node).
 */
export type UsageReference = {
	cpu_request: number,
	cpu_limit: number,
	memory_request: number,
	memory_limit: number,
	cpu_allocatable: number,
	memory_allocatable: number,
};

/**  One sample: epoch milliseconds, millicores and bytes. */
export type UsageSample = {
	t: number,
	cpu_millicores: number,
	memory_bytes: number,
};

/**  Where a chart's samples come from. */
export type UsageSource = 
/**  The history the app collects from metrics-server. */
"metrics_server" | "prometheus";

/**  Where vulnerabilities come from (#536). */
export type VulnSource = 
/**  The Trivy Operator's reports only. */
"cluster" | 
/**  A Trivy or Grype on this computer only. */
"local" | 
/**  The reports, and the local scanner for images they do not cover. */
"cluster_then_local";

/**  One vulnerability of a full report. */
export type Vulnerability = {
	/**  `CVE-2024-1234`, `GHSA-...`. */
	id: string,
	/**  The package or library (`openssl`, `golang.org/x/net`). */
	package: string,
	installed_version: string,
	/**  Empty when no fix is known. */
	fixed_version: string,
	severity: Severity,
	/**  The CVSS score the scanner reports, 0 when none. */
	score: number | null,
	title: string,
	/**  The advisory's page, empty when none. */
	link: string,
	/**  Whether it is known to be exploited, and how likely (#537). */
	exploit: Exploit,
};

/**  What a listing could show. */
export type VulnsState = 
/**  Reports were read (`images` may still be empty after filters). */
"ok" | 
/**  The cluster does not serve VulnerabilityReports: no Trivy Operator. */
"no_operator" | 
/**  The CRD is there but no report exists in the scope yet. */
"no_reports" | 
/**  The user may not list the reports in the scope. */
"forbidden";

/**  The result of [`report::image_vulns`]. */
export type VulnsSummary = {
	source: ScanSource,
	state: VulnsState,
	/**  The namespace asked for, empty for all namespaces. */
	namespace: string,
	/**
	 *  The namespaces that were read when the cluster-wide list is not
	 *  allowed (empty when it is, or when one namespace was asked for).
	 */
	namespaces_read: string[],
	/**  One row per image, worst first, after the filters. */
	images: ImageVulns[],
	/**
	 *  Namespaces where listing the reports was not allowed, while other
	 *  namespaces were read (or, with the [`VulnsState::Forbidden`] state,
	 *  the namespaces asked for).
	 */
	forbidden_namespaces: string[],
	/**
	 *  With [`VulnsState::Forbidden`] for chosen namespaces: the reports
	 *  may be listed across all namespaces (so offering that helps).
	 *  False otherwise.
	 */
	all_namespaces_allowed: boolean,
	/**
	 *  Running images no report covers (before the filters). Images in
	 *  namespaces whose reports were not read (the read budget ran out)
	 *  are neither counted here nor listed: a note says so.
	 */
	unscanned: number,
	/**  Plain notes: what could not be read, what was cut. */
	notes: string[],
};

/**  A message on a table watch's channel. */
export type WatchMessage = 
/**
 *  One coalesced set of table rows: the first batch is a full
 *  snapshot, later ones are incremental.
 */
{ type: "batch"; snapshot: boolean; applied: ResourceRow[]; 
/**  Keys of removed rows. */
deleted: string[] } | 
/**  The watch's connection state changed. */
{
	type: "state",
} & WatchState;

/**  Connection state of a watch. */
export type WatchState = 
/**  Waiting for the first full list. */
{ state: "connecting" } | 
/**  Receiving updates. */
{ state: "live" } | 
/**
 *  The watch failed and is backing off before retrying (it re-lists
 *  by itself when it has to).
 */
{ state: "reconnecting"; error: string } | 
/**
 *  The server refused the list or watch (403). Retrying would not help,
 *  so the watch stops; `error` is the server's message.
 */
{ state: "forbidden"; error: string } | 
/**
 *  The kind cannot be watched (no `watch` verb), so it is listed again
 *  every `interval_secs` seconds instead ([`crate::poll`]). Changes show
 *  up late: the table is not live.
 */
{ state: "polling"; interval_secs: number };

/**
 *  A workload container that runs an image: the Deployment (not its
 *  ReplicaSet), StatefulSet, DaemonSet, Job, CronJob or bare Pod.
 */
export type Workload = {
	/**  `Deployment`, `ReplicaSet`, `Pod`, ... */
	kind: string,
	namespace: string,
	name: string,
	container: string,
};

/**  Options of a workload log stream. */
export type WorkloadLogOptions = WorkloadLogOptions_Serialize | WorkloadLogOptions_Deserialize;

/**  Options of a workload log stream. */
export type WorkloadLogOptions_Deserialize = {
	/**  One container name for every pod; `None` follows all containers. */
	container?: string | null,
	/**
	 *  Applies to the pods present when the stream starts; pods that appear
	 *  later are read from their beginning.
	 */
	tailLines?: number | null,
	sinceSeconds?: number | null,
	timestamps?: boolean | null,
};

/**  Options of a workload log stream. */
export type WorkloadLogOptions_Serialize = {
	/**  One container name for every pod; `None` follows all containers. */
	container: string | null,
	/**
	 *  Applies to the pods present when the stream starts; pods that appear
	 *  later are read from their beginning.
	 */
	tailLines: number | null,
	sinceSeconds: number | null,
	timestamps: boolean | null,
};

/**  A change in which pods a merged stream is following. */
export type WorkloadNotice = {
	kind: WorkloadNoticeKind,
	/**  Empty for `truncated`. */
	pod: string,
	container: string,
	message: string,
	/**  For `truncated`: the stream limit and how many containers are waiting. */
	limit: number,
	skipped: number,
};

export type WorkloadNoticeKind = 
/**  A per-container stream started (a pod appeared). */
"started" | 
/**  The container exited and its log ended. */
"ended" | 
/**  The pod was deleted. */
"deleted" | 
/**  The stream failed; see `message`. */
"failed" | 
/**  More containers match than the stream limit: `skipped` are waiting. */
"truncated";

/**
 *  How a workload object counts. Not every kind uses every status: see
 *  [`statuses_of`].
 */
export type WorkloadStatus = 
/**
 *  Pods: phase Running without a waiting error. Controllers: every
 *  desired replica ready. Jobs: still running. Cron jobs: a job is
 *  active.
 */
"Running" | 
/**  Pods: phase Pending. Controllers: some replicas not ready yet. */
"Pending" | 
/**
 *  Pods: a container waits on an error (CrashLoopBackOff,
 *  ImagePullBackOff, ...).
 */
"Error" | 
/**
 *  Pods: phase Failed. Controllers: a rollout past its deadline or a
 *  replica that could not be created. Jobs: the Failed condition.
 */
"Failed" | 
/**  Pods: phase Succeeded. Jobs: complete. */
"Succeeded" | 
/**  Jobs and cron jobs with `spec.suspend`. */
"Suspended" | 
/**  Cron jobs waiting for their next run. */
"Scheduled" | 
/**  A pod phase this version does not know. */
"Unknown";

/**  A message on a Workloads overview feed's channel. */
export type WorkloadsMessage = 
/**  A new overview (sent when it changed, at most about once a second). */
{ type: "update"; overview: WorkloadsOverview } | 
/**  The feed's connection state changed. */
{
	type: "state",
} & WatchState;

/**  The Workloads overview of the selected namespaces. */
export type WorkloadsOverview = {
	/**
	 *  In sidebar order. A kind the user may not list anywhere in the scope
	 *  is left out, with a note.
	 */
	kinds: KindCounts[],
	/**  Failed first, then the oldest; at most [`MAX_PROBLEMS`]. */
	problems: ProblemWorkload[],
	problems_total: number,
	/**  Warning events about workload objects, newest first. */
	events: EventInfo[],
	/**  What is missing or narrowed, and why. */
	notes: string[],
};

/* Tauri Specta runtime */
type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

type EventEmitTo<T> = [T] extends [null] ? (target: __TAURI_EVENT.EventTarget | string) => Promise<void> : (target: __TAURI_EVENT.EventTarget | string, payload: T) => Promise<void>;

function makeEvent<TListen, TEmit = TListen>(name: string, serialize?: (payload: TEmit) => unknown, deserialize?: (payload: any) => TListen) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<TListen>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: TEmit) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => __TAURI_EVENT.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => target.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    });

    return Object.assign(fn, base);
}
